<?php require_once __DIR__.'/../config.php';if(current_user()&&current_user()['role']==='admin')redirect('admin/dashboard.php');$pageTitle='Admin login';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=db()->prepare('SELECT id,name,email,password,role FROM users WHERE email=? AND role=\'admin\'');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>'admin'];redirect('admin/dashboard.php');}$error='Invalid administrator credentials.';}require __DIR__.'/../includes/header.php';?><section class="form-page"><div class="container"><div class="form-shell"><div class="eyebrow">Restricted area</div><h1>Administrator login</h1><p class="form-intro">Sign in to review student applications.</p><?php if($error): ?><div class="alert error" style="width:100%;margin:0 0 15px"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label>Email address</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn form-submit">Log in to admin panel</button></form><div class="form-foot"><a href="<?= BASE_URL ?>/index.php">Return to website</a></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
